mapper.update:
update category_brand
set update_time = now(), is_deleted = 1
where id=#{id}

mapper.select:
select cb.*, c.name AS categoryName, b.name AS BrandName, b.logo from brand b INNER JOIN category_brand cb ON b.id = cb.brand_id INNER JOIN category c ON c.id = cb.category_id
and cb.brand_id=#{brandId}
and cb.category_id=#{categoryId}
and cb.is_deleted=0
order by cb.id desc
